"맞붙어(공격 · 반격) 준 피해의 절반(올림)만큼 이 유닛의 체력이 참. 맞선 상대의 남은 체력보다 많이는 차지 않음(연쇄로 친 뒤 유닛은 세지 않음). 다 찬 뒤 남는 몫은 이번 턴 체력 +.": "This unit restores HP equal to half (rounded up) the damage it dealt in a Clash (attack or counter). It can't restore more than the opponent's remaining HP (units behind hit by Chain don't count). Any excess after full HP becomes HP + this turn.",
"맞붙어(공격 · 반격) 피해를 준 상대가 살아남으면 그 유닛에 출혈이 {0} 쌓임(걸 때마다 더해짐). 그 뒤 이번 전투에서 맞붙음이 하나 끝날 때마다(출혈이 걸린 그 맞붙음부터) 출혈 유닛은 체력이 출혈만큼 깎임(방어 · 보호막과 상관없이. [가호 N]이 있으면 깎일 때마다 N 줄어듦). 출혈로 쓰러뜨려도 이 유닛이 쓰러뜨린 것으로 침(강탈 · 제물). 천족 유닛에게는 출혈이 1 적게 붙음(빛의 몸).": "If an enemy it damaged in a Clash (attack or counter) survives, that unit gains {0} Bleed (adds up each time). After that, each time a Clash ends in this battle (starting with the one that applied it), the bleeding unit loses HP equal to its Bleed (regardless of DEF and Barrier; with [Aegis N], each loss is reduced by N). A unit defeated by Bleed counts as defeated by this unit (Plunder, Offering). Celestial units receive 1 less Bleed (body of light).",
