"오라 — 이 유닛이 전장에 있는 동안 양옆 {0}칸 안의 아군 유닛은 [흡혈]을 얻음. 준비 단계부터 걸리고, 전투가 시작된 뒤 받은 오라는 이 유닛이 쓰러져도 그 턴이 끝날 때까지 남음(받은 유닛에 ◎ 칩).": "Aura — while this unit is on the Field, allied units within {0} slots on either side gain [Lifesteal]. Applies from the Prep Phase; auras received after battle starts last until the end of that turn even if this unit is defeated (◎ chip on the receiving unit).",
