"(코인 뒷면 · 운명은 아직 던지지 않은 코인에만). 유닛의 공격·방어·체력 코인은 순번이 같으면 동전 하나라 함께 앞·뒷면이 됩니다(공격 2개·방어 1개면 동전 2개). 장착한 아이템의 코인도 함께 세고, 동전은 최대 5개입니다. 내 코인은 내가": "(Coin Tails · Fate only affect Coins not yet tossed). A unit's Attack · Defense · HP Coins with the same order number share one physical coin and land heads · tails together (2 Attack · 1 Defense = 2 coins). Equipped items' Coins count too, up to 5 coins. You set your own Coins with",
