"결속한 아군이 쓰러지면 가진 피가 모두 바로 뒤 아군에게 옮겨 간다. 남의 피를 머금고 전투에서 살아남으면 다음 턴 준비 때 그 피 주인들이 쓰러질 때의 공격만큼 공격이 오른다(그 턴만).": "When a bound ally falls, all its blood passes to the ally directly behind. A unit that holds others' blood and survives the battle gains Attack equal to those owners' Attack when they fell, during next turn's prep (that turn only).",
