"유지비 {0}를 낼 에테르가 없음": "No Ether to pay Upkeep {0}",
"유지비 −{0}": "Upkeep −{0}",
"유지비가 모자랍니다": "Not enough Upkeep",
"유지비가 모자랍니다: 결정화하거나 유닛을 소각하세요.": "Not enough Upkeep: Crystallize or burn a unit.",
"으로 보내기": "send to",
"으로, 상대 코인은 상대가 세웁니다(5초가 지나면 저절로 멈춤). 양쪽이 멈추면 나온 대로 스탯이 바뀐 뒤 공격 → 반격이 이어집니다. 피해 = 공격 − 방어(최소 0). 쓰러진 유닛과 쓴 마법은 그 자리에서 부서지고 남은 카드는 바로 왼쪽으로 당겨집니다. 피해는 그 턴 안에서만 쌓이고, 턴이 끝나면 회복됩니다.": "; the opponent stops their own coins (they stop automatically after 5 seconds). Once both stop, stats change by the results, then attack → counter follow. Damage = ATK − DEF (min 0). Defeated units and used spells break on the spot and remaining cards shift left at once. Damage builds only within that turn and heals when the turn ends.",
"은 감소 효과를,": " ignores decreases,",
"은 증가 효과를 받지 않습니다(증가·감소 효과 = 마법·특수능력·코인·저주로 스탯이 오르내리는 것). 셋 다 받은 피해는 그대로 쌓이므로 체력만큼 피해를 입으면 쓰러집니다. 코인 때문에 체력이 0 이하가 되면 그 유닛은 쓰러져 소각 더미로 갑니다.": " ignores increases (increase/decrease = stats going up or down from spells, special abilities, coins or curses). For all three, damage taken still accumulates, so a unit is defeated once damage equals its HP. If coins drop HP to 0 or below, that unit is defeated and goes to the burn pile.",
"은 증가·감소 효과를 모두,": " ignores both increases and decreases,",
"을": "",
"을 내고 그 코인만 다시 던집니다. 맞붙을 때마다 한 번(이미 정해진 방어 코인은 다시 던질 수 없음). 준비 단계에서 남겨 둔 에테르를 여기에 씁니다 (남은 에테르는 다음 턴으로 넘어가지 않습니다).": " to pay it and rethrow just that coin. Once per clash (an already-set defense coin can't be rethrown). Ether saved during prep is spent here (leftover Ether doesn't carry to the next turn).",
"을 누르면 에테르 1": " for Ether 1",
"을 받습니다.": " is applied.",
"을 일시적으로 얻습니다 (한 턴에 한 번, 그 턴에만).": " temporarily (once per turn, that turn only).",
"이 되어 바로, 그리고 매 턴 에테르가 1 늘어납니다. 바친 카드는 소각장으로 갑니다.": ", and right away, plus every turn, Ether goes up by 1. The offered card goes to the Pyre.",
