"— 고른 카드를 덱에 되돌리고 같은 장수를 새로 뽑습니다(생명은 줄지 않음).": "— returns the chosen cards to the deck and draws the same number anew (costs no Life).",
"— 그 단체의 유닛 · 마법 · 아이템.": "— that group's units · spells · items.",
"— 그 전투에서 처음 맞붙을 때 한 번, 끝까지 그대로": "— once at its first clash in that battle, kept to the end",
"— 끝 —": "— The End —",
"— 남은 카드는 다음 턴에. 쓸 카드가 적은 턴에는 남은 에테르로 전투 중": "— leftover cards next turn. On turns with few cards to play, use leftover Ether in battle",
"— 누르면 대기실로.": "— tap to go to the Lobby.",
"— 맞붙을 때마다 새로 던진다": "— thrown anew each clash",
"— 방어 0인 유닛에게 순환을 걸면 그렇습니다. 🔒 고정된 스탯은 제자리에 남고, ▲ 버팀 · ▼ 눌림은 기준값에서 멈춥니다. 표시를 이번 턴만 거는 마법도 있습니다(강철 맹세 · 나이테 등).": "— that's what happens when you cast a cycle on a unit with 0 DEF. 🔒 Locked stats stay put, and ▲ Braced · ▼ Suppressed stop at the base value. Some spells apply markers for this turn only (Steel Oath · Tree Rings, etc.).",
"— 살아남으면 다음 턴부터 매 턴 그만큼 에테르가 빠진다. 유지비는 레벨 − 1까지(금빛 아이콘이 적어도 하나).": "— if it survives, that much Ether is drained every turn from the next turn. Upkeep goes up to level − 1 (at least one gold icon).",
"— 에테르 1로 그 코인만 다시 던진다 (− 코인은 앞면을 누른다)": "— rethrow just that coin for 1 Ether (− coins: tap heads)",
"— 카드를 사도 줄지 않습니다.": "— doesn't go down when you buy cards.",
"— 하루에 한 번 열리는 길에서 여덟 관문과 망각의 숲을 지납니다.": "— a path that opens once a day, through eight gates and the Forest of Oblivion.",
", 그 아래 금빛 막대가 경험치. 이름 옆은 전적과 승률.": ", and the gold bar below it is EXP. Next to the name: record and win rate.",
", 둘레의 빈 자리 {0}개는": ", the {0} empty spots around the ring are",
", 상대 대기열의": ", of the opponent's Line",
