": 감소 효과를 받지 않습니다(피해 제외).": ": unaffected by decreases (except damage).",
": 공격 마법은 공격 턴, 방어 마법은 방어 턴에만 냅니다. 한쪽에 치우치지 않게.": ": play Attack Spells only on attack turns, Defense Spells only on defense turns. Keep them balanced.",
": 공격하는 쪽이 먼저 놓고 준비 완료, 방어하는 쪽은 그 배치를 보고 놓습니다. 마법은 뒷면이라 상대에게 보이지 않습니다.": ": the attacker places first and readies, then the defender places after seeing that setup. Spells are face down, hidden from the opponent.",
": 받은 피해가 낫고, 다음 턴에는 공격과 방어가 바뀝니다. 공격 턴과 방어 턴이 한 번씩 지나면": ": damage taken heals, and next turn attack and defense swap. After one attack turn and one defense turn,",
": 빈 아이콘이 많은 큰 유닛은 강하지만 매 턴 에테르를 먹습니다. 두세 장이면 충분합니다.": ": big units with many empty icons are strong but eat Ether every turn. Two or three is plenty.",
": 에테르는 결정이 쌓이며 천천히 늘어납니다. 낮은 레벨(1~3) 카드가 넉넉해야 초반에 칸을 채울 수 있습니다.": ": Ether grows slowly as crystals build up. You need plenty of low-level (1~3) cards to fill slots early.",
": 저절로 진행됩니다. 코인을 세우고, 손해 본 코인(뒷면 + 코인 · 앞면 − 코인)을 뒤집을지 고르는 것만 합니다.": ": it plays out automatically. You only stop your coins and choose whether to flip losing coins (tails on + coins · heads on − coins).",
": 증가 · 감소 효과를 모두 받지 않습니다(그 스탯의 코인은 던지지 않음).": ": unaffected by both increases and decreases (that stat's coins aren't thrown).",
": 증가 효과를 받지 않습니다. 증가 · 감소 효과는 마법 · 특수능력 · 코인 · 저주로 스탯이 오르내리는 것입니다. 기준은 카드에 적힌 값(아이템이 더한 값 포함)이고, 받은 피해는 셋 다 그대로 쌓입니다. 체력에는 고정이 없습니다.": ": unaffected by increases. Increases · decreases are stats going up or down from spells · special abilities · coins · curses. The base is the value printed on the card (including what items add), and damage taken accumulates for all three. HP has no Locked.",
": 턴이 시작되면 두 사람 모두 핸드를 {0}장까지 뽑고,": ": at the start of a turn both players draw up to {0} cards,",
": 핸드 카드는 결정이 됩니다. 쓰기 애매한 카드도 결정으로 바뀌어 에테르가 됩니다.": ": hand cards become crystals. Even awkward cards turn into crystals and become Ether.",
". 관리자는": ". Admins",
". 그 턴에 카드를 냈거나 소각했으면 할 수 없습니다.": ". Not allowed if you played or burned a card that turn.",
". 마법은 효과. [능력]에 마우스를 올리면 뜻.": ". Spells: effect. Hover over an [ability] for its meaning.",
". 모래시계가 남은 시간을 세고(카드를 뽑는 동안은 멈춤), 0이 되면 준비 완료처럼 턴이 넘어갑니다 — 에테르가 모자라도 묻지 않고 마칩니다. (관리자는 설정에서 끌 수 있습니다)": ". The hourglass counts the time left (paused while drawing), and at 0 the turn passes as if you pressed Ready — even if Ether is short, it ends without asking. (Admins can turn this off in Settings)",
". 어두운 결정은 다음 턴이 되면 다시 밝아집니다. 쓰지 않고 남긴 에테르는 다음 턴으로 넘어가지 않습니다.": ". Dark crystals light up again next turn. Ether you leave unspent doesn't carry to the next turn.",
". 이제 {0} 카드를 낼 수 있습니다. 바친 카드는 소각장으로 가지만 결정은 판 끝까지 남아": ". Now you can play {0} cards. The offered card goes to the Pyre, but the crystal stays until the end of the game",
