"(0 아래로는 내려가지 않음). 체력이 0이 되면 쓰러져 부서지고, 남은 카드는 왼쪽으로 당겨집니다.": "(never below 0). At 0 HP a unit is defeated and breaks, and remaining cards shift left.",
"(Enter). 전투는 저절로 진행됩니다.": "(Enter). Battle plays out automatically.",
"(N만큼 줄임)에는 막힙니다. \"맨 앞 유닛 2개\" · \"적 유닛 2\" · \"아군 유닛 2\"처럼 유닛을 세는 마법은 그 사이에 놓인 마법 칸을 건너뛰고 유닛만 셉니다.": "(reduce by N) blocks it. Spells that count units, like \"front 2 units\" · \"2 enemy units\" · \"2 allied units\", skip spell slots in between and count only units.",
