"(그림자 강탈 · 그림자 손아귀)는 상대 카드를 가져와 내 전장 맨 뒤에 놓습니다 — 유닛이면 이번 턴 내 유닛(공격 턴이면 내 다른 유닛들 다음에 공격), 뒷면 마법이면 내 마법으로 발동합니다. 가져온 카드는 전투가 끝나면 원래 주인의 소각장으로 갑니다(": "(Shadow Plunder · Shadow Grasp) takes an opponent's card and puts it at the back of your field — a unit becomes your unit this turn (on an attack turn it attacks after your other units), a face-down spell triggers as your spell. Taken cards go to their original owner's Pyre when the battle ends (",
