"오른쪽 아래 세로 숫자, 위부터 공 · 방 · 체. 금빛 숫자 · 자물쇠는 아래로 깎이지 않는 값.": "Vertical numbers at the lower right, from top: ATK · DEF · HP. Gold numbers · locks are values that can't be lowered.",
