"준비 단계에 핸드 1장을": "In the Prep Phase, take 1 hand card:",
"준비를 다 했으면": "When you're done preparing,",
"지갑. 전투 · 순례 · 수레바퀴로 모으고 상점에서 카드를 삽니다. 누르면 상점으로.": "Wallet. Earn them from battles · Pilgrimage · the Wheel, and buy cards at the Shop. Tap to go to the Shop.",
"지금 덱으로 컴퓨터와 한 판. 전장의 중요한 곳마다 짧은 안내가 뜹니다.": "One match against the Computer with your current deck. Short tips pop up at key spots on the Field.",
"지금은 서버가 없어 이 기기에만 저장됩니다.": "No server right now, so it's saved only on this device.",
"지도": "Map",
"직접 공격 보너스": "Direct Attack Bonus",
"집니다.": "you lose.",
"찹니다. 새 카드는 맨 왼쪽 빈 칸에 놓이고, 카드가 부서지면 남은 카드가 바로 왼쪽으로 당겨집니다(\"이 칸에 부른다\" 소환물은 그 자리를 채웁니다). 순서는 전장의 카드를 끌어 옮겨 바꿉니다.": "— new cards go to the leftmost empty slot, and when a card is destroyed the rest shift left right away (“summon to this slot” tokens fill that spot). Change the order by dragging cards on the Field.",
"창병": "Spearman",
"찾기 — 예: 유지비, 코인": "Search — e.g. Upkeep, Coin",
"찾는 말이 없습니다.": "No matches found.",
"처럼 부호 없는 숫자와 함께면 유닛 값과 상관없이 그 값이 됩니다. 유닛과 아이템의 표시가 겹치면 아이템을 따릅니다.": ", it becomes that value regardless of the unit's own. When unit and item markers overlap, the item's takes priority.",
"처럼 적힌 클래스가 유닛 오른쪽 아래 열 맨 위의 클래스 아이콘과 같으면 장착. [공용]은 누구에게나.": ", matches the class icon at the top of the unit's lower-right column, it can be equipped. [Universal] items fit anyone.",
"처음 시작하기": "Getting Started",
"처음에는 0": "starts at 0",
"처음에는 에테르 0": "Ether Starts at 0",
"처음이라면 1부터 차례로. 마친 장에는 ✓가 붙습니다. 규칙 전부는": "New here? Go in order from 1. Finished chapters get a ✓. All the rules are in the",
"처음이라면 여기부터": "New? Start Here",
"처음이라면 이 순서로": "New? Follow This Order",
"척후병": "Scout",
"첫 핸드에서 고른 카드를 한 번 바꿉니다. 생명은 줄지 않습니다.": "Swap the cards you choose from your opening hand once. No Life is lost.",
"체력 −2 −1●": "HP −2 −1●",
"체력 −N": "HP −N",
"체력을 깎습니다 — 맞붙기 · 반격 · 투척 · 연쇄 · 꿰뚫기, 그리고": "reduces HP — Clash · Counter · Throw · Chain · Pierce, and",
"체력이 0이 되는 유닛은 쓰러집니다": "A unit whose HP becomes 0 is defeated",
"체력이 N 깎입니다 — 대부분의 마법 · 사격 · 불씨 · 축전.": "HP drops by N — most spells · Shot · Ember · Capacitor.",
"출정의 단": "Sortie Altar",
"카드 숫자 옆": "Next to a card's numbers, the",
"카드 이름 아래 · 상점 단추 옆의 색이 등급입니다. 희귀할수록 상점 재고가 적습니다. 유니크 · 스페셜 · 강화는 덱에 한 장만 넣을 수 있습니다. 강화는 같은 카드 3장을 합쳐서만 얻습니다.": "Grade is shown by the color under the card name · next to the Shop button. The rarer the card, the less Shop stock. Unique · Special · Empowered cards are limited to one per deck. Empowered cards are obtained only by fusing 3 copies of the same card.",
"카드 읽기": "Reading Cards",
"카드를 내는 힘.": "The power to play cards.",
"카드를 내면 결정이 어두워진다": "Playing Cards Dims Crystals",
"카드를 누르면 상대 전장 오른쪽에 원본 카드가 크게 뜹니다(레벨 · 클래스 · 설명 · 지금 스탯). 내 카드면 왼쪽에 단추도 나옵니다. 다시 누르기 · 빈 곳 누르기 · Esc로 닫습니다. 소각장을 누르면 맨 위 카드를 봅니다.": "Tap a card to show the original card large to the right of the opponent's Field (Level · class · description · current stats). For your own cards, buttons also appear on the left. Close by tapping again · tapping empty space · Esc. Tap the Pyre to see its top card.",
"카드를 뽑을 때마다": "whenever you draw cards:",
"카드에 적힌 앞쪽부터": "in the order listed on the card",
"칸 번호 순서대로 진행된다 — 1 · 2번이 공격하고, 3번 공격 마법이 뒤집혀 발동하고, 4번 기사가 공격한다.": "Proceeds in slot order — slots 1 · 2 attack, the Attack Spell in slot 3 flips and triggers, then the knight in slot 4 attacks.",
"칸 없이 바로 발동": "Triggers instantly, no slot",
"칸에 서서 싸운다 · 유지비": "Stands in a slot and fights · Upkeep",
