"같은 카드 3장 합치기 — 일반 → 강화 · 고급 → 레어 뽑기": "Combine 3 copies of the same card — Common → Empowered · Superior → Rare draw",
"같은 카드는 {0}장까지입니다.": "Up to {0} copies of the same card.",
