"기본 덱을 불러왔습니다. 저장해야 반영됩니다.": "Starter deck loaded. Save to apply.",
"깃발을 누르면 출정 · 덱 조정": "Click a banner to deploy · edit deck",
"깃발을 최대 3개까지 무료로 고릅니다 — 진영마다 하나까지, 적어도 하나. 고른 깃발마다 기본 덱 {0}장과 그 단체의 다른 카드를 1장씩 받습니다. 고르지 않은 깃발은 쓸 수 없습니다. (고른 깃발을 다시 누르면 풀립니다)": "Pick up to 3 banners for free — at most one per Faction, at least one. For each chosen banner you get the {0}-card starter deck and 1 copy of each other card of that group. Unchosen banners cannot be used. (Click a chosen banner again to deselect it)",
"끌어서 왼쪽 서에 놓기": "Drag onto the book on the left",
"난이도": "Difficulty",
"남은 카드만": "Remaining Cards Only",
"남음": "Left",
"내 공격 턴에만": "My attack turns only",
"내 덱": "My Deck",
"내 덱 카드 등급으로 거르기": "Filter by my deck's card grades",
"내 덱 카드 종류로 거르기": "Filter by my deck's card types",
"내 덱과 같은 세기(덱 점수 100%)": "Same strength as my deck (Deck Score 100%)",
"내 덱에 이 조건의 카드가 없습니다.": "My deck has no cards matching this condition.",
"내 방어 턴에만": "My defense turns only",
"누르기": "Click",
"누르기: 크게 보기 고정 · 더블클릭: 덱에 가득이면 모두 빼기 · 우클릭: 1장 빼기": "Click: pin enlarged view · Double-click: remove all if full in deck · Right-click: remove 1",
"누르기: 크게 보기 고정 · 더블클릭: 덱에 없으면 가득 넣기, 가득이면 모두 빼기 · 우클릭: 1장 빼기": "Click: pin enlarged view · Double-click: fill if not in deck, remove all if full · Right-click: remove 1",
"다른 유니크를 빼고 넣으세요.": "Remove another Unique first.",
"다시 들어오려면 로그인해야 합니다.": "You must log in to come back.",
"다시 받기 {0}초": "Resend in {0}s",
