"/* 고리 안의 필멸자 땅: 서북 아다만트의 용광로 불 · 서남 푸른숲의 숲빛 · 동 비술의 흰 첨탑 불빛 */": "/* Mortal lands inside the ring: Adamant's furnace fire in the northwest · forest light of the Bluewood in the southwest · white spire lights of the arcane east */",
