"/* 동쪽 너머의 빈 땅: 색이 빠지고 고리의 선도 지워진다 */": "/* Empty land beyond the east: colors fade and the ring's line is erased */",
"/* 빈 땅: 회색 번짐과 잔금 */": "/* Empty land: gray smudges and fine cracks */",
"/* 칠룡의 고리 여덟 자리: 원소색 빛 일곱, 동쪽은 빈 점선 홈 */": "/* Eight seats of the Ring of Seven Dragons: seven elemental lights, the east an empty dotted socket */",
"0.) { /* 날개짓: 어깨에서 멀수록 크게 */": "0.) { /* Wingbeat: bigger farther from the shoulder */",
