"끄기 이 창에서 Ctrl + C": "To stop: Ctrl + C in this window",
"끝난 로그인 {0}개 · 필멸자 {1}명": "{0} expired logins · {1} Mortals",
"나감": "Logged Out",
"너무 큽니다.": "Too large.",
"다른 모험가의 데이터는 바꿀 수 없습니다.": "You can't change another adventurer's data.",
