"로그인 실패": "Login Failed",
"로그인이 필요합니다. (서버의 세션이 끝났습니다)": "Login required. (Your server session ended)",
"메일 {0}{1}": "Email {0}{1}",
"모든 기기에서 나감": "Logged out on all devices",
