"덱 조정실에서 저장해야 대전 · 순례에 나갑님.": "Decks must be saved in the Deck Workshop to use them in matches · Pilgrimage.",
"덱 코드 — 지금 덱을 글로 복사하거나, 받은 덱 코드로 꾸밉님": "Deck Code — copy the current deck as text, or build from a received deck code",
"덱 코드가 아닙님. E1: 로 시작하는 글을 붙여 넣어 주세요.": "Not a deck code. Paste text that starts with E1:.",
"덱 코드로 {0}장을 넣었습님. 저장해야 반영됩님.": "Loaded {0} cards from the deck code. Save to apply.",
"덱 코드를 복사했습님.": "Deck code copied.",
