"두 기기가 본 거래 내용이 다릅님.": "The two devices see different trade contents.",
"두 기기를 잇지 못했습님. 다시 준비해 주세요.": "Couldn't connect the two devices. Please get ready again.",
"두 기기의 게임 버전(카드 데이터)이 다릅님. 같은 버전으로 맞춘 뒤 거래하세요.": "The two devices have different game versions (card data). Match versions before trading.",
