"두 사람 모두 준비했습님. 대전을 시작하세요.": "Both players are ready. Start the match.",
"두 사람의 게임 버전이 다릅님. 같은 ETHERION 폴더(같은 버전)로 해 주세요.": "Your game versions differ. Please both use the same ETHERION folder (same version).",
