"뒷면! 깎이지 않습님": "Tails! No reduction",
"들어가지 못했습님.": "Could not join.",
"들어갈 수 없습님.": "Can't join.",
"들어온 것이 기한에 성사됩님. 조건과 다른 제안도 낼 수 있고, 올린 사람은 기한 전에 아무 참여나 골라 바로 성사시킬 수 있습님.": "to arrive closes the deal at the deadline. Proposals that differ from the terms are also allowed, and the poster can pick any offer before the deadline to close the deal immediately.",
"등록 없이 필멸자로. 아홉 단체의 덱과 모든 카드를 씁님.": "Play as a Mortal without registering. Use the decks of all nine Banners and every card.",
"등록되지 않은 이름입님. '새 모험가'로 등록하거나 '로그인 없이 시작'을 눌러 주세요.": "That name isn't registered. Register as a 'New Adventurer' or press 'Play Without Login'.",
"등록하고 {trade.newHours}시간이 지나고 대전 {trade.newMatches}판을 마쳐야 거래할 수 있습님.": "You can trade {trade.newHours} hours after registering and after finishing {trade.newMatches} matches.",
"등록하지 못했습님.": "Registration failed.",
"등록한 이름과 암호로 들어갑님.": "Sign in with your registered name and password.",
"등록할 때 고른 깃발(최대 3개)의 덱만 쓸 수 있습님. 순례 · 컴퓨터와 대전에서 카드를 얻고, 상점에서 사고팔 수도 있습님.": "You can only use decks of the banners (up to 3) chosen at registration. Earn cards from Pilgrimage · vs Computer, and buy · sell in the Shop.",
"또 앞면… 그대로 깎입님": "Heads again… reduced as is",
"라고 적힌 마법(마법이 부른 유닛의 공격도). 피해 3이 방어 1인 유닛에게는 2가 들어갑님.": "spells (including attacks by units summoned by spells). 3 damage against a unit with 1 Defense deals 2.",
"라운드가 올바르지 않습님.": "Invalid round.",
"레거시 카드는 덱에 넣을 수 없습님: {0}": "Legacy cards can't be added to a deck: {0}",
"레거시 카드는 어떤 덱에도 넣을 수 없고, 합성 재료 · 결과로도 쓰이지 않습님.": "Legacy cards cannot be put in any deck, and are not used as Fusion materials · results.",
"레거시 카드와 이미 최대 장수만큼 가진 카드는 나오지 않고, 그 몫은 나머지가 나눕님.": "Legacy cards and cards you already own at max copies do not appear; their share is split among the rest.",
"레벨 {0} 이하 상대 유닛이 없어 그림자가 허공을 쥐었음": "No enemy unit of Level {0} or lower — the shadow grasped at air",
"레어 이상": "Rare or better",
"로 그 코인만 다시 던집님.": "and re-roll just that coin.",
"로 내 카드를 걸고 원하는 카드나 조각을 적어 보세요. 다른 모험가는 이 게시판에서 참여합님.": " to put up your cards and name the cards or Shards you want. Other adventurers make offers on this board.",
"로 다시 굴릴 수 있습님": " lets you reroll",
"로 다시 굴릴 수 있습님. 굴릴 코인은 눌러서 바꿉님": " lets you reroll. Tap a coin to choose which to roll",
"로 데려온 유닛은 살아남으면 상대 전장 맨 뒤로 돌아갑님).": "return to the back of the opponent's Field if they survive).",
