"로그인하지 못했습님.": "Sign-in failed.",
"룰북 파일이 없습님.": "Rulebook file not found.",
"를 고르면 지금은 아무것도 받지 않고 다음 관문으로 갑님. 남긴 보상은 오늘 안에 언제든 고를 수 있고, 고르지 않으면 자정에 조각으로 들어옵님.": "— choose it and you receive nothing now and move on to the next gate. You can claim the saved reward anytime today; if you don't, it arrives as Shards at midnight.",
"를 던져 셋에 함께 붙습님.": " are thrown and apply to all three.",
"를 열면 위쪽 머리에서 고릅님. 언제든 다시 열 수 있습님.": "and pick from the header at the top. You can reopen them anytime.",
"를 열면 위쪽에서 고릅님. 다음은": "— open it and choose at the top. Next up:",
"린데어 자유시 상점 · 세 진영 아홉 단체의 카드가 모두 모임": "Free City of Lindair Shop · Cards from all nine orders of the three factions",
"마렌시아의 노래 유닛에게는 화상이 1 적게 붙음(물의 몸).": "Marencia's Song units receive 1 less Burn (body of water).",
"마법도 대기열의 한 자리입님. 같은 때 양쪽 마법이 모두 발동할 수 있으면": "Spells also take a place in the Line. When spells on both sides can trigger at the same time, they go",
"마법은 발동할 때 생명을 바치고 겨눈 상대에게 [제물 증표]를 남깁니다 — 그 유닛이 이번 전투에서 쓰러지면 바친 생명이 돌아오고 카드는 내 소각장으로 갑님.": "spells offer Life when they trigger and leave an [Offering Mark] on the targeted enemy — if that unit is defeated this battle, the offered Life returns and the card goes to your Pyre.",
"마음에 들지 않는 카드를 눌러 고르면 덱에 되돌리고 같은 장수를 새로 뽑습님. 한 번만 할 수 있고, 생명은 줄지 않습님.": "Tap cards you don't like to return them to the deck and draw the same number anew. You can do this only once, and it costs no Life.",
