"맨 앞 뒤에 상대 유닛이 없어 화살이 닿지 않았음": "No enemy unit behind the front one — the arrow found no mark",
"머리표 [R라운드 T턴 단계] · 칸 = 전장 칸 번호(1이 맨 앞) · 공/방/체 = 공격/방어/남은 체력/최대 체력 · ⤷ = 전투의 한 수에서 바뀐 것(「」= 떠오른 글자, → 뒤는 그 수가 끝난 뒤 스탯, 칸 번호는 그 순간의 칸 — 쓰러진 카드가 빠지면 앞으로 당겨짐)": "Header [R round T turn phase] · slot = Field slot number (1 is the front) · ATK/DEF/HP = Attack/Defense/HP left/max HP · ⤷ = what changed in one battle step (「」= floating text; after → are the stats once that step ends; slot numbers are as of that moment — when a defeated card leaves, the rest move forward)",
