"없는 퀘스트입님.": "No such quest.",
"에 넣으면 바로 시작합님.": ", the match starts right away.",
"에 더해지고, 모험가의 보유 목록에도 영구히 남습님.": " and also stay in your Adventurer's collection forever.",
"에 들어 있으면 장착됩님.": "tag beside its name.",
"에 맞춰 꾸밉님. 어려움은 수를 더 깊이 읽습님.": ". Hard reads moves more deeply.",
"에 불이 번졌음": " caught the spreading fire",
"에 섹션별로 있습님. 대기실의 「룰북」 명판으로도 엽님.": ", section by section. You can also open it from the “Rulebook” plaque in the Lobby.",
"에 역병이 옮았음": " caught the Plague",
"에 있습님.": ".",
"에 장착합님(핸드에서 유닛 위로 끌어 놓기). 유닛 하나에 하나.": "— equip it there (drag from your hand onto the unit). One per unit.",
"에 적혔습님.": ".",
