"연결하지 못했습님. 잠시 뒤 다시 해 주세요.": "Couldn't connect. Please try again shortly.",
"예전 방식: 다섯 글자 번호를 주고받아 바로 잇습님": "Old method: exchange a five-letter code to connect directly",
