"오늘 시작할 수 있는 판({0}판)을 다 썼습님.": "You've used today's available matches ({0}).",
"오늘은 더 싸울 수 없습님": "No more battles today",
"오늘은 이미 퀘스트를 바꿨습님. 내일 다시 바꿀 수 있습님.": "You've already swapped a quest today. You can swap again tomorrow.",
"오늘의 {0}판을 모두 썼습님. {1}번째 관문까지 지났습님.": "You've used all {0} of today's matches. You passed up to gate #{1}.",
"오늘의 순례를 마쳤습님": "Today's pilgrimage is done",
"오늘의 첫 승 보상은 남겨 두었습님(위에서 언제든 고름). 이 판은 전투 정산(작은 조각)만 있습님.": "You've saved today's first-win reward (claim it above anytime). This match only gives the battle payout (a few Shards).",
