"오래 응답이 없어 방에서 나왔습님.": "Left the room after no response for a long time.",
"오른쪽 아래 열 맨 위 동그라미(무도 · 무장 · 마도 · 기도). 아이템의 [○○ 전용]과 같아야 장착됨.": "The circle at the top of the lower-right column (Primal · Armed · Arcane · Devout). Must match an item's [○○ only] to equip it.",
"온라인 연결 도구를 받지 못했습님. 인터넷 연결을 확인해 주세요.": "Couldn't load the online connection tool. Please check your internet connection.",
"올려 둔 거래가 없습님.": "You have no trades posted.",
"올린 사람만 고를 수 있습님.": "Only the poster can pick.",
"올린 사람만 내릴 수 있습님.": "Only the poster can take it down.",
"와 동전이 코인입님. 내 코인은": "with its discs is a Coin. You stop your own coins with",
"와 함께 씁님. 실시간 거래는": ". Live trades are made",
"왼쪽. 단체마다 덱 하나. 상자를 누르면 그 덱이 가운데에 펼쳐집님. 막대 10칸 = {0}장, 금빛이면 저장된 덱(출전 가능).": "Left. One deck per Banner. Tap a box to open that deck in the center. 10 bar segments = {0} cards; gold means a saved deck (ready to play).",
"요청을 읽지 못했습님.": "Couldn't read the request.",
